<?php
declare(strict_types=1);if(!defined('ABSPATH')){exit;}$messages=['created'=>__('Workflow draft created.','atlas-platform'),'restored'=>__('The existing workflow request was restored.','atlas-platform'),'failed'=>__('The workflow draft could not be created.','atlas-platform')];
?><div class="atlas-preview-wrap"><div class="atlas-shell"><main class="atlas-resource-main"><p class="atlas-eyebrow"><?php echo esc_html__('Operational guidance','atlas-platform'); ?></p><h1><?php echo esc_html__('Workflows','atlas-platform'); ?></h1><p><?php echo esc_html__('Follow published, source-linked operational steps in the current organization context.','atlas-platform'); ?></p><?php if(isset($messages[$notice])):?><div class="notice notice-<?php echo $notice==='failed'?'error':'success'; ?> inline"><p><?php echo esc_html($messages[$notice]); ?><?php if($versionId!==''):?> <code><?php echo esc_html($versionId); ?></code><?php endif;?></p></div><?php endif;?>
<?php if($workflows===[]):?><section class="atlas-empty-state"><span class="dashicons dashicons-editor-ol" aria-hidden="true"></span><h2><?php echo esc_html__('No published workflows are available.','atlas-platform'); ?></h2><p><?php echo esc_html__('Authorized authors can prepare a draft below. Publication remains a governed review action.','atlas-platform'); ?></p></section><?php else:?><div class="atlas-library-list"><?php foreach($workflows as$workflow):?><article class="atlas-library-row"><div><div class="atlas-card-meta"><span><?php echo esc_html(ucfirst($workflow->scope)); ?></span><span><?php echo esc_html(sprintf(__('Version %d','atlas-platform'),$workflow->version)); ?></span><span><?php echo esc_html(sprintf(_n('%d step','%d steps',$workflow->stepCount,'atlas-platform'),$workflow->stepCount)); ?></span></div><h2><a href="<?php echo esc_url(add_query_arg(['page'=>'atlas-workflow','id'=>$workflow->id],admin_url('admin.php'))); ?>"><?php echo esc_html($workflow->title); ?></a></h2><p><?php echo esc_html($workflow->summary); ?></p></div><a class="button" href="<?php echo esc_url(add_query_arg(['page'=>'atlas-workflow','id'=>$workflow->id],admin_url('admin.php'))); ?>"><?php echo esc_html__('Open workflow','atlas-platform'); ?></a></article><?php endforeach;?></div><?php endif;?>
<?php if(current_user_can('atlas_manage_workflows')):?><section class="atlas-admin-panel"><h2><?php echo esc_html__('Create workflow draft','atlas-platform'); ?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="atlas-authoring-form"><input type="hidden" name="action" value="atlas_create_workflow"><input type="hidden" name="idempotency_key" value="<?php echo esc_attr(wp_generate_uuid4()); ?>"><?php wp_nonce_field('atlas_create_workflow'); ?><div class="atlas-form-columns"><label><?php echo esc_html__('Title','atlas-platform'); ?><input required maxlength="255" name="title"></label><label><?php echo esc_html__('Slug','atlas-platform'); ?><input required maxlength="191" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" name="slug"></label><label><?php echo esc_html__('Scope','atlas-platform'); ?><select name="scope"><option value="organization"><?php echo esc_html($organization?->name??__('Current organization','atlas-platform')); ?></option><?php if(current_user_can('atlas_manage_atlas')):?><option value="platform"><?php echo esc_html__('Platform','atlas-platform'); ?></option><?php endif;?></select></label><label><?php echo esc_html__('Source Resource Version ID','atlas-platform'); ?><input maxlength="36" name="source_resource_version_id"></label></div><label><?php echo esc_html__('Summary','atlas-platform'); ?><textarea required maxlength="2000" rows="3" name="summary"></textarea></label><label><?php echo esc_html__('Ordered steps','atlas-platform'); ?><textarea required rows="10" name="steps" aria-describedby="atlas-step-help"></textarea></label><p id="atlas-step-help" class="description"><?php echo esc_html__('One step per line: Title | Instruction | Requirement | Optional warning. Maximum 50 steps.','atlas-platform'); ?></p><p><button class="button button-primary" type="submit"><?php echo esc_html__('Create workflow draft','atlas-platform'); ?></button></p></form></section><?php endif;?></main></div></div>
